import React, { useState } from "react";
import "./BikeRental.css";

// ✅ 15 Bike Images
const bikeImages = [
  "https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcRpsBtOabw5QY_bYyI9bkVO1DzX4nmhNvq7fg&s",
  "data:image/jpeg;base64,",
  "https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcSp8NWAYXaxkkNiKBNpE_oKGa2-SYUanM7Y3g&s",
  "data:image/jpeg;base64,",
  "data:image/jpeg;base64,",
  "https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcRDj4Kixjiwme9BUJiVNHHnUT2Ue8rkVm5WWw&s",
  "https://etimg.etb2bimg.com/photo/106592360.cms",
  "data:image/jpeg;base64,",
  "data:image/jpeg;base64,",
  "data:image/jpeg;base64,",
  "data:image/jpeg;base64,",
  "data:image/jpeg;base64,",
  "data:image/jpeg;base64,",
  "data:image/jpeg;base64,",
  "data:image/jpeg;base64,",
];

// ✅ Realistic Bike + Fuel Mapping
const bikeBrands = [
  { brand: "Honda Shine", fuel: "Petrol" },
  { brand: "Yamaha R15", fuel: "Petrol" },
  { brand: "KTM Duke", fuel: "Petrol" },
  { brand: "Bajaj Pulsar", fuel: "Petrol" },
  { brand: "TVS Raider", fuel: "Petrol" },

  { brand: "Ola S1", fuel: "Electric" },
  { brand: "Ather 450X", fuel: "Electric" },
  { brand: "TVS iQube", fuel: "Electric" },
  { brand: "Bajaj Chetak EV", fuel: "Electric" },

  { brand: "Bajaj Freedom CNG", fuel: "CNG" },
];

const bikeRentals = Array.from({ length: 15 }, (_, i) => {
  const bike = bikeBrands[i % bikeBrands.length];

  return {
    id: i + 1,
    name: `${bike.brand} ${i + 1}`,
    fuel: bike.fuel,

    price:
      bike.fuel === "Electric"
        ? `₹${500 + (i % 5) * 100} / day`
        : bike.fuel === "CNG"
        ? `₹${400 + (i % 5) * 100} / day`
        : `₹${700 + (i % 10) * 100} / day`,

    owner: `Owner ${i + 1}`,
    model: 2021 + (i % 3),
    phone: `98${Math.floor(10000000 + Math.random() * 90000000)}`,

    avatar: `https://randomuser.me/api/portraits/men/${i + 10}.jpg`,

    // ✅ One image per bike (no repeat)
    image: bikeImages[i],
  };
});
const BikeRental = () => {
  const [search, setSearch] = useState("");
  const [fuelFilter, setFuelFilter] = useState("All");

  const fuels = ["All", "Petrol", "CNG", "Electric"];

  const filteredBikes = bikeRentals.filter((bike) => {
    const matchesSearch =
      bike.name.toLowerCase().includes(search.toLowerCase());

    const matchesFuel =
      fuelFilter === "All" || bike.fuel === fuelFilter;

    return matchesSearch && matchesFuel;
  });

  return (
    <div className="bike-rental-page">
      <h1>🏍️ Rent a Bike</h1>

      {/* 🔍 SEARCH */}
      <input
        type="text"
        placeholder="Search bikes..."
        value={search}
        onChange={(e) => setSearch(e.target.value)}
        className="search-input"
      />

      {/* 🔥 FILTER */}
      <div className="filter-buttons">
        {fuels.map((fuel, i) => (
          <button
            key={i}
            className={fuelFilter === fuel ? "active-filter" : ""}
            onClick={() => setFuelFilter(fuel)}
          >
            {fuel === "Petrol" && "⛽"}
            {fuel === "CNG" && "🟢"}
            {fuel === "Electric" && "⚡"}
            {fuel === "All" && "🏍️"} {fuel}
          </button>
        ))}
      </div>

      {/* 🚗 CARDS */}
      <div className="card-grid">
        {filteredBikes.length > 0 ? (
          filteredBikes.map((bike) => (
            <div className="card" key={bike.id}>
              <img src={bike.image} alt={bike.name} className="card-image" />

              <div className="card-info">
                <h3>{bike.name}</h3>

                {/* ✅ Fuel Badge */}
                <p className={`fuel ${bike.fuel.toLowerCase()}`}>
                  {bike.fuel}
                </p>

                <p>{bike.price}</p>

                <div className="card-buttons">
                  <button className="info-btn">ℹ️</button>
                  <button className="book-btn">Book Now</button>
                </div>
              </div>
            </div>
          ))
        ) : (
          <h3 style={{ marginTop: "30px" }}>No Bikes Found</h3>
        )}
      </div>
    </div>
  );
};

export default BikeRental;